-- M-Core Onboarding Checklist - part 05a: seed checklist master v1 (sections A,B,C,D) from the M-Core onboarding PDF.
-- Run after part 4. Idempotent: inserts only what is missing in version 1. A,B,C,E = UTAMA; B,C,E submissions are urgent.
DO $seed$
DECLARE vid uuid; secs jsonb := '[["A","Maklumat Syarikat & Perundangan","Company & Legal Information",1],["B","Pendaftaran Statutori & Pematuhan","Statutory & Compliance Registration",1],["C","Maklumat Perbankan","Banking Information",1],["D","Carta Akaun & Baki Pembukaan","Chart of Accounts & Opening Balances",0]]';
 items jsonb := '[["A1","Sijil Pendaftaran Syarikat (SSM)","Company Registration Certificate (SSM)","PDF, Borang 9 / Seksyen 17","PDF, Form 9/Section 17","r","doc",[{"key":"name","bm":"Nama syarikat","en":"Company name","target":"name"},{"key":"ssm_no","bm":"No. pendaftaran","en":"Registration no.","target":"ssm_no"},{"key":"incorporation_date","bm":"Tarikh diperbadankan","en":"Incorporation date","target":"incorporation_date","kind":"date"}],"scan_ssm_certificate",null,1,"settings",{}],["A2","Nama Syarikat, No. Pendaftaran & Alamat Perniagaan","Company Name, Registration No. & Business Address","Ikut SSM","As per SSM","r","form",[{"key":"name","bm":"Nama syarikat","en":"Company name","target":"name"},{"key":"ssm_no","bm":"No. pendaftaran","en":"Registration no.","target":"ssm_no"},{"key":"address","bm":"Alamat baris 1","en":"Address line 1","target":"address"},{"key":"address_line2","bm":"Alamat baris 2","en":"Address line 2","target":"address_line2"},{"key":"postcode","bm":"Poskod","en":"Postcode","target":"postcode"},{"key":"city","bm":"Bandar","en":"City","target":"city"},{"key":"state","bm":"Negeri","en":"State","target":"state"}],null,null,0,"settings",{}],["A3","Logo Syarikat (resolusi tinggi)","Company Logo (high-resolution)","PNG/SVG, latar lutsinar","PNG/SVG, transparent bg","r","doc",[{"key":"logo_url","bm":"Logo","en":"Logo","target":"logo_url","kind":"logo"}],null,null,0,"settings",{}],["A4","No. Pendaftaran Perniagaan Rasmi","Official Business Registration Number (for invoices/DO)","Untuk kepala dokumen (invois/DO)","For document headers","r","form",[{"key":"ssm_no","bm":"No. pendaftaran rasmi","en":"Official registration no.","target":"ssm_no"}],null,null,0,"settings",{}],["A5","Jenis Perniagaan / Industri","Nature of Business / Industry Type","Untuk konfigurasi modul","For module config","r","form",[{"key":"industry","bm":"Jenis perniagaan / industri","en":"Nature of business / industry"}],null,null,0,null,{}],["A6","Tarikh Penutup Tahun Kewangan","Financial Year End (FYE)","cth. 31 Dis","e.g. 31 Dec","r","form",[{"key":"fye","bm":"Tarikh penutup tahun kewangan","en":"Financial year end"}],null,null,0,"accounting",{}],["A7","Senarai Cawangan / Lokasi (jika ada)","List of Branches / Locations (if any)","Untuk tetapan pelbagai cawangan","For multi-branch setup","i","list",[],null,"branch_name,address,city,state,phone",0,null,{}],["A8","Orang Hubungan Syarikat & Admin Utama","Company Contact Person & Designated Admin","Nama, e-mel, telefon","Name, email, phone","r","form",[{"key":"contact_name","bm":"Nama orang hubungan","en":"Contact person name"},{"key":"email","bm":"E-mel syarikat","en":"Company email","target":"email"},{"key":"phone","bm":"Telefon syarikat","en":"Company phone","target":"phone"},{"key":"admin_name","bm":"Admin utama","en":"Designated admin"}],null,null,0,"settings",{}],["B1","No. Rujukan Majikan KWSP","EPF (KWSP) Employer Reference Number","Untuk penyelarasan i-Akaun","For i-Akaun sync","r","form",[{"key":"epf_employer_no","bm":"No. rujukan majikan KWSP","en":"EPF employer ref. no.","sensitive":true}],null,null,0,"hr",{}],["B2","Kod Majikan PERKESO","SOCSO/EIS (PERKESO ASSIST) Employer Code","Untuk kiraan caruman","For contribution calc","r","form",[{"key":"socso_employer_code","bm":"Kod majikan PERKESO","en":"SOCSO employer code","sensitive":true}],null,null,0,"hr",{}],["B3","No. Majikan LHDN & Tetapan PCB","LHDN Employer No. (E Number) & PCB Setup","Untuk potongan PCB","For PCB deduction","r","form",[{"key":"lhdn_e_no","bm":"No. majikan LHDN (E)","en":"LHDN employer no. (E)","sensitive":true},{"key":"pcb_note","bm":"Tetapan PCB","en":"PCB setup"}],null,null,0,"hr",{}],["B4","Pendaftaran HRDF/HRD Corp (jika berkenaan)","HRDF/HRD Corp Registration (if applicable)","Kiraan levi","Levy calculation","i","doc",[{"key":"hrdf_no","bm":"No. pendaftaran HRDF","en":"HRDF registration no."}],null,null,1,"hr",{}],["B5","No. Pendaftaran SST (jika berkenaan)","SST/Sales Tax Registration No. (if applicable)","Untuk cukai pada invois","For tax on invoices","i","form",[{"key":"sst_gst_no","bm":"No. pendaftaran SST","en":"SST registration no.","target":"sst_gst_no"}],null,null,1,"settings",{}],["B6","Butiran Bayaran Zakat (jika berkenaan)","Zakat Payment Details (if applicable)","Untuk potongan gaji","For payroll deduction","i","form",[{"key":"zakat_note","bm":"Butiran bayaran zakat","en":"Zakat payment details"}],null,null,0,"hr",{}],["C1","Nama Bank, No. Akaun & Nama Pemegang Akaun","Bank Name, Account Number & Account Holder Name","Untuk rekod bayaran","For payment records","r","doc",[{"key":"bank_name","bm":"Bank","en":"Bank","target":"bank_name"},{"key":"account_number","bm":"No. akaun","en":"Account no.","target":"account_number","sensitive":true},{"key":"account_name","bm":"Nama pemegang","en":"Account holder","target":"account_name"}],"scan_bank_statement",null,0,"settings",{}],["C2","Contoh Penyata Bank (terkini, untuk kalibrasi parser)","Bank Statement Sample (latest, for parser calibration)","Format PDF","PDF format","r","doc",[],null,null,0,"accounting",{}],["C3","Butiran Gateway Pembayaran (jika guna)","Payment Gateway Details (Billplz/FPX, if used)","Tetapan API key","API key setup","i","form",[{"key":"gateway","bm":"Gateway (cth. Billplz/FPX)","en":"Gateway (e.g. Billplz/FPX)"},{"key":"gateway_note","bm":"Nota (jangan tampal API key penuh)","en":"Note (do not paste full API keys)"}],null,null,0,"settings",{}],["C4","Baki Bank Pembukaan (pada tarikh potongan)","Opening Bank Balance (as at cut-off date)","Setiap akaun","Per account","r","form",[{"key":"opening_bank_balance","bm":"Baki pembukaan (RM)","en":"Opening balance (RM)","kind":"money"},{"key":"cutoff_date","bm":"Tarikh potongan","en":"Cut-off date","kind":"date"}],null,null,0,"accounting",{"view":"opening-balance"}],["D1","Carta Akaun Sedia Ada (jika berpindah sistem)","Existing Chart of Accounts (if migrating)","Excel/CSV","Excel/CSV","i","list",[],null,"account_code,account_name,account_type,parent_code",0,"accounting",{}],["D2","Baki Percubaan / Baki Pembukaan","Opening Trial Balance / Opening Balances","Pada tarikh potongan","As at cut-off date","r","list",[],null,"account_code,account_name,debit,credit",0,"accounting",{"view":"opening-balance"}],["D3","Senarai Belum Terima (AR)","Outstanding Receivables (AR) Listing","Ikut pelanggan, dengan aging","By customer, with aging","r","list",[],null,"customer,invoice_no,invoice_date,due_date,amount,balance",0,"sales",{}],["D4","Senarai Belum Bayar (AP)","Outstanding Payables (AP) Listing","Ikut pembekal, dengan aging","By supplier, with aging","r","list",[],null,"supplier,bill_no,bill_date,due_date,amount,balance",0,"purchasing",{"view":"bills"}],["D5","Daftar Aset Tetap (jika ada)","Fixed Assets Register (if any)","Kos, tarikh, kadar susut nilai","Cost, date, depreciation rate","i","list",[],null,"asset_name,category,purchase_date,cost,depreciation_rate",0,"accounting",{"view":"fixed-assets"}],["D6","Pemetaan Akaun Lalai bagi Setiap Modul","Default Account Mappings per Module","Jualan/POS/Gaji/Perbelanjaan","Sales/POS/Payroll/Expense","r","form",[{"key":"mapping_note","bm":"Pemetaan akaun lalai","en":"Default account mapping"}],null,null,0,"accounting",{}]]';
BEGIN
 SELECT id INTO vid FROM public.cob_master_versions WHERE version = 1 AND deleted_at IS NULL;
 IF vid IS NULL THEN
  INSERT INTO public.cob_master_versions (version, status, note, published_at) VALUES (1, 'published', 'M-Core onboarding checklist v1', now()) RETURNING id INTO vid;
 END IF;
 INSERT INTO public.cob_master_sections (version_id, key, name_bm, name_en, is_core, sort_order)
 SELECT vid, e->>0, e->>1, e->>2, (e->>3)::int = 1, ascii(e->>0) - 65 FROM jsonb_array_elements(secs) e
 WHERE NOT EXISTS (SELECT 1 FROM public.cob_master_sections s WHERE s.version_id = vid AND s.key = e->>0 AND s.deleted_at IS NULL);
 INSERT INTO public.cob_master_items (version_id, section_key, code, sort_order, label_bm, label_en, note_bm, note_en, requirement, item_type,
   fields, ai_action, template_header, track_expiry, urgent, module_page, module_params)
 SELECT vid, left(e->>0, 1), e->>0, substr(e->>0, 2)::int, e->>1, e->>2, e->>3, e->>4,
   CASE WHEN e->>5 = 'i' THEN 'if_applicable' ELSE 'required' END, e->>6, e->7, e->>8, e->>9, (e->>10)::int = 1,
   left(e->>0, 1) IN ('B','C','E'), e->>11, coalesce(e->12, '{}'::jsonb)
 FROM jsonb_array_elements(items) e
 WHERE NOT EXISTS (SELECT 1 FROM public.cob_master_items m WHERE m.version_id = vid AND m.code = e->>0 AND m.deleted_at IS NULL);
END
$seed$;
